def _iter():
    if views:
        items = db.view_names()
    else:
        items = db.table_names(fts4=fts4, fts5=fts5)
    for name in items:
        row = [name]
        if counts:
            row.append(db[name].count)
        if columns:
            cols = [c.name for c in db[name].columns]
            if csv:
                row.append("\n".join(cols))
